mapper.update:
UPDATE operation_base.t_operation_base_user
SET password = #{password}
WHERE delete_flag = false
  AND operation_user_code = #{userCode}
  AND enable_flag = true

mapper.select:
SELECT t1.id, t1.operation_user_code, t1.operation_user_name, t1.id_number, t1.phone_number, t1.gender, t1.role_level, t1.enable_flag, t1.remark, t1.create_time, t1.update_time, t1.delete_flag, t2.group_code FROM operation_base.t_operation_base_user t1 LEFT JOIN operation_base.t_operation_base_group_map_user t2 ON t1.operation_user_code = t2.user_code AND t2.delete_flag = false WHERE t1.delete_flag = false
AND t1.operation_user_name LIKE '%'|| #{operationUserFilterConditionDTO.operationUserName} ||'%'
AND t1.role_level = #{operationUserFilterConditionDTO.roleLevel}
AND t1.enable_flag = #{operationUserFilterConditionDTO.enableFlag}

SELECT id, operation_user_code, operation_user_name, id_number, phone_number, password, gender, role_level, enable_flag, remark, create_time, update_time, delete_flag FROM operation_base.t_operation_base_user WHERE operation_user_code IN
#{userCode}
AND delete_flag = false
